import initSqlJs from 'sql.js'
import sqlWasmUrl from 'sql.js/dist/sql-wasm.wasm?url'

// Only entry point the app should use to read game data.
// Backed by a prebuilt SQLite file (public/data/empire-connect.sqlite, generated by
// `npm run import-data`) loaded client-side via sql.js, plus provinces.geojson for boundaries.
let dbPromise = null

function getDb() {
  if (!dbPromise) {
    dbPromise = (async () => {
      const SQL = await initSqlJs({ locateFile: () => sqlWasmUrl })
      // 'no-cache' makes the browser re-check with the server on every load, so a rebuilt database
      // is picked up straight away instead of an old cached copy.
      const buf = await fetch(`${import.meta.env.BASE_URL}data/empire-connect.sqlite`, { cache: 'no-cache' }).then((r) => r.arrayBuffer())
      return new SQL.Database(new Uint8Array(buf))
    })()
  }
  return dbPromise
}

function all(db, sql, params = []) {
  const stmt = db.prepare(sql)
  stmt.bind(params)
  const rows = []
  while (stmt.step()) rows.push(stmt.getAsObject())
  stmt.free()
  return rows
}

// Occupations with no end year are still ongoing; the app's year range stops here.
export const PRESENT_YEAR = 2025

// A province is the unit of the game: one city, with a record of who occupied it when.
export async function getProvinces() {
  const db = await getDb()
  return all(
    db,
    `SELECT id, city_name AS name, city_lat AS lat, city_lon AS lon, city_source AS citySource,
            area_km2 AS areaKm2, country, continent, region
     FROM province ORDER BY id`,
  )
}

// Shaped as the game logic's "holdings" ({ city, empireId, nation, start, end }): `city` is the
// province id, `empireId`/`nation` the occupier. `isNation` is false for peoples and cultures
// (Bantu, Thai, hunter-gatherers...), which the game won't link provinces through.
export async function getOccupations() {
  const db = await getDb()
  const rows = all(
    db,
    `SELECT o.province_id AS city, k.id AS empireId, k.name AS nation, k.is_nation AS isNation,
            o.start_year AS start, COALESCE(o.end_year, ${PRESENT_YEAR}) AS end
     FROM occupation o JOIN occupier k ON k.id = o.occupier_id`,
  )
  return rows.map((r) => ({ ...r, isNation: !!r.isNation }))
}

// Colony/dependency -> parent realm links (see src/game/realms.js).
export async function getRealmLinks() {
  const db = await getDb()
  return all(
    db,
    `SELECT l.occupier_id AS occupierId, l.overlord_id AS overlordId, k.name AS overlordName,
            l.start_year AS start, l.end_year AS end, l.kind
     FROM realm_link l JOIN occupier k ON k.id = l.overlord_id`,
  )
}

export async function getOccupiers() {
  const db = await getDb()
  return all(db, 'SELECT id, name, color, is_nation AS isNation FROM occupier').map((r) => ({ ...r, isNation: !!r.isNation }))
}

let boundaries = null

// GeoJSON FeatureCollection of province boundaries (feature.properties.id = province id).
export function getProvinceBoundaries() {
  boundaries ??= fetch(`${import.meta.env.BASE_URL}data/provinces.geojson`, { cache: 'no-cache' }).then((r) => r.json())
  return boundaries
}
